import test from 'node:test';import assert from 'node:assert/strict';import {parseItemQuery,itemLink,websiteEnquiry} from '../../listing.mjs';import {fixture} from './fixture.mjs';
test('website item links preserve website identity only',()=>{const item=fixture().items[1],link=itemLink(item,'https://brownnoodyai-sketch.github.io/');assert.deepEqual(parseItemQuery(new URL(link).search),{kind:'PRODUCT',id:item.id,islandCode:'AGATTI'});});
test('WhatsApp handoff sends item name and website context, not Core item token',()=>{const item=fixture().items[0],text=new URL(websiteEnquiry('919446944562','AGATTI',item,'en','https://brownnoodyai-sketch.github.io/')).searchParams.get('text');assert.match(text,/Service: Kayaking/);assert.match(text,/NOODY_SOURCE:WEBSITE/);assert.match(text,/NOODY_WEBSITE_ITEM:/);assert.doesNotMatch(text,/NOODY_ITEM:/);});
test('Malayalam enquiry keeps customer-facing language and exact item name',()=>{const item=fixture().items[0],text=new URL(websiteEnquiry('919446944562','AGATTI',item,'ml')).searchParams.get('text');assert.match(text,/ഹലോ NOODY/);assert.match(text,/Service: Kayaking/);});
test('general enquiry has no item identity',()=>{const text=new URL(websiteEnquiry('919446944562',null,null,'en','https://example.com/')).searchParams.get('text');assert.match(text,/NOODY_SOURCE:WEBSITE/);assert.doesNotMatch(text,/NOODY_WEBSITE_ITEM/);});
